/// Given a vector of integers and three distinct indices `i`, `j`, `k`,
/// returns a pair of the two indices corresponding to the highest-valued
/// elements among those three. The returned pair is ordered so that
/// the value at the first index is >= the value at the second index.
fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    let vi = valores[i];
    let vj = valores[j];
    let vk = valores[k];

    // Determine which index holds the largest value,
    // then choose the second index as the larger of the remaining two.
    if vi >= vj && vi >= vk {
        // i is the largest
        if vj >= vk {
            (i, j)
        } else {
            (i, k)
        }
    } else if vj >= vi && vj >= vk {
        // j is the largest
        if vi >= vk {
            (j, i)
        } else {
            (j, k)
        }
    } else {
        // k is the largest
        if vi >= vj {
            (k, i)
        } else {
            (k, j)
        }
    }
}

